CREATE DEFINER=`root`@`localhost` EVENT `dar_monedas_cada_minuto` ON SCHEDULE EVERY 1 MINUTE STARTS '2026-08-03 16:08:16' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    UPDATE usuarios
    SET monedas = monedas + 100
    WHERE monedas < 1000;
END$$

